    public FXTrade load( @RequestParam(required=true) UUID uuid ) {    	
    	FXTrade entity = null;

    	try {  
    		entity = service.getFXTrade( new FXTradeFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load FXTrade using Id " + uuid );
            return null;
        }

        return entity;
    }

